import re

def simulate(trace_file):
    mem = {}
    intr_status = 0
    with open(trace_file) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'): continue
            parts = line.split()
            cmd = parts[0]
            if cmd == 'write_reg':
                addr = int(parts[1], 16) & 0xffff
                data = int(parts[2], 16)
                if addr == 0x0003:
                    intr_status &= ~data
                else:
                    mem[addr] = data
                    # Launch registers
                    if addr in [0x100d, 0x1404, 0x3402, 0x2c0e] and data == 1:
                        intr_status = 0xffffffff
            elif cmd == 'read_reg':
                addr = int(parts[1], 16) & 0xffff
                mask = int(parts[2], 16)
                expected = int(parts[3], 16)
                if addr == 0x0003:
                    val = intr_status
                else:
                    val = mem.get(addr, 0)

                if (val & mask) != (expected & mask):
                    print(f"FAIL: {trace_file}: addr {hex(addr)} expected {hex(expected)} mask {hex(mask)} got {hex(val)}")
                    return False
    return True

